package org.apache.commons.math.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Comparator;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.ConvergenceException;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.optimization.ConvergenceChecker;
import org.apache.commons.math.optimization.GoalType;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.FunctionEvaluationException;
import org.apache.commons.math3.optim.univariate.GoalType;
import org.apache.commons.math3.optim.univariate.UnivariateRealFunction;
import org.apache.commons.math3.optim.univariate.UnivariateRealPointValuePair;
import org.apache.commons.math3.random.JDKRandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for MultiStartUnivariateRealOptimizer.optimize(FUNC, GoalType, double, double).
 */
public class MultiStartUnivariateRealOptimizer_optimize_TriageGen2Test {

    private BaseUnivariateRealOptimizer<UnivariateRealFunction> mockOptimizer;
    private MultiStartUnivariateRealOptimizer optimizer;
    private final int starts = 3;

    @Before
    public void setUp() {
        mockOptimizer = mock(BaseUnivariateRealOptimizer.class);
        optimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, starts, new JDKRandomGenerator());
    }

    @Test
    public void testOptimizeMinimization() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction f = x -> x * x;
        GoalType goal = GoalType.MINIMIZE;
        double min = -10.0;
        double max = 10.0;

        // The method calls optimize(f, goal, min, max, min + 0.5 / (max - min))
        // For min=-10, max=10, startValue = -10 + 0.5 / 20 = -10 + 0.025 = -9.975
        double expectedStartValue = min + 0.5 / (max - min);

        UnivariateRealPointValuePair expectedResult = new UnivariateRealPointValuePair(0.0, 0.0);

        when(mockOptimizer.optimize(f, goal, min, max, expectedStartValue))
            .thenReturn(expectedResult);

        // Act
        UnivariateRealPointValuePair result = optimizer.optimize(f, goal, min, max);

        // Assert
        assertNotNull(result);
        assertEquals(0.0, result.getPoint(), 1e-10);
        assertEquals(0.0, result.getValue(), 1e-10);
    }

    @Test
    public void testOptimizeMaximization() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction f = x -> -x * x;
        GoalType goal = GoalType.MAXIMIZE;
        double min = -5.0;
        double max = 5.0;
        double expectedStartValue = min + 0.5 / (max - min);

        UnivariateRealPointValuePair expectedResult = new UnivariateRealPointValuePair(0.0, 0.0);

        when(mockOptimizer.optimize(f, goal, min, max, expectedStartValue))
            .thenReturn(expectedResult);

        // Act
        UnivariateRealPointValuePair result = optimizer.optimize(f, goal, min, max);

        // Assert
        assertNotNull(result);
        assertEquals(0.0, result.getPoint(), 1e-10);
    }

    @Test(expected = FunctionEvaluationException.class)
    public void testOptimizeThrowsException() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction f = x -> {
            throw new FunctionEvaluationException(new RuntimeException("Evaluation failed"));
        };
        GoalType goal = GoalType.MINIMIZE;
        double min = 0.0;
        double max = 1.0;

        when(mockOptimizer.optimize(f, goal, min, max, min + 0.5 / (max - min)))
            .thenThrow(new FunctionEvaluationException(new RuntimeException("Evaluation failed")));

        // Act
        optimizer.optimize(f, goal, min, max);
    }

    @Test
    public void testOptimizeWithExtremeRange() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction f = x -> x;
        GoalType goal = GoalType.MINIMIZE;
        double min = 0.0;
        double max = 1e-10; // Very small range
        double expectedStartValue = min + 0.5 / (max - min);

        UnivariateRealPointValuePair expectedResult = new UnivariateRealPointValuePair(0.0, 0.0);

        when(mockOptimizer.optimize(f, goal, min, max, expectedStartValue))
            .thenReturn(expectedResult);

        // Act
        UnivariateRealPointValuePair result = optimizer.optimize(f, goal, min, max);

        // Assert
        assertNotNull(result);
    }
}
